        {
          typ: "tabelle",
          caption: `Naturschutzfachliche Prüfungen für Freiflächen-Solarparks in Deutschland, Stand ${STAND}`,
          kopf: ["Instrument", "Rechtsgrundlage", "Leitfrage", "Ergebnis"],
          zeilen: [
