          zeilen: [
            ["Fläche", `${fmt(S200.ha)} ha`, `${fmt(S500.ha)} ha`],
            ["Leistung (Süd, fest)", `rund ${fmt(S200.mwp, 1)} MWp`, `rund ${fmt(S500.mwp, 1)} MWp`],
